/// A signed-in profile of [role] (Visual Impairment, the preset that turns on
/// the most accessibility behaviour), without Firebase.
class SweepProfile extends ProfileNotifier {
  SweepProfile(this.role);

  final UserRole role;

  @override
  UserProfile? build() => UserProfile(
        id: 'sweep-profile',
        name: 'Test User',
        role: role,
        disabilityType: DisabilityType.visual,
        createdAt: DateTime(2026),
      );
}

